/* Painted art for the Silver Order, keyed by stable id (generated by tools/make_silverart.py from assets/silver/<id>.png;
   see docs/silver_art.md for the list):
   - items:     relic, charm and legendary ids (so_*), and shop ids (so_s_*) -> RELICART / RELIC_IMG (shop under 'shop-')
   - abilities: ability ids (so_*) -> UI_ART (the command card and the gear sheet)
   - spells:    hero spell ids (so_lioncharge, so_dawnbreak, so_sentence) -> UI_ART, and SPELL_ART points the spell at it
   - heroes:    hero ids (so_lion, so_dawn, so_judge) -> HERO_ART (the portrait)
   An id with no painting keeps its glyph. Nothing here is required at load time: the maps are applied once everything
   (uiart, heroart, heroes) has loaded, so this file can sit among the split asset scripts (ASSETS in build.sh). */
const SILVERART = {"items":{"so_scales":"data:image/webp;base64,","so_quill":"data:image/webp;base64,","so_lens":"data:image/webp;base64,","so_spur":"data:image/webp;base64,","so_censerlet":"data:image/webp;base64,","so_handbell":"data:image/webp;base64,","so_link":"data:image/webp;base64,","so_oathring":"data:image/webp;base64,","so_beads":"data:image/webp;base64,","so_mirror":"data:image/webp;base64,","so_reliq":"data:image/webp;base64,","so_standard":"data:image/webp;base64,","so_bossshield":"data:image/webp;base64,","so_goatsfoot":"data:image/webp;base64,","so_rosary":"data:image/webp;base64,","so_grailcup":"data:image/webp;base64,","so_zenith":"data:image/webp;base64,","so_anvil":"data:image/webp;base64,","so_thurible":"data:image/webp;base64,","so_clapper":"data:image/webp;base64,","so_c_vial":"data:image/webp;base64,","so_c_hourglass":"data:image/webp;base64,","so_c_beads":"data:image/webp;base64,","so_c_matins":"data:image/webp;base64,","so_c_tithe":"data:image/webp;base64,","so_c_sunstone":"data:image/webp;base64,","so_c_wardknot":"data:image/webp;base64,","so_c_echo":"data:image/webp;base64,","so_lionshield":"data:image/webp;base64,","so_sunbolt":"data:image/webp;base64,","so_firstchain":"data:image/webp;base64,","so_truegrail":"data:image/webp;base64,","so_firstlight":"data:image/webp;base64,","so_lasthammer":"data:image/webp;base64,","so_saintcenser":"data:image/webp;base64,","so_silvermere":"data:image/webp;base64,","so_dawncrown":"data:image/webp;base64,","so_lawbook":"data:image/webp;base64,","so_martyr":"data:image/webp;base64,","so_oathblade":"data:image/webp;base64,","so_s_gauntlets":"data:image/webp;base64,","so_s_spurs":"data:image/webp;base64,","so_s_glass":"data:image/webp;base64,","so_s_rosary":"data:image/webp;base64,","so_s_mail":"data:image/webp;base64,","so_s_chalk":"data:image/webp;base64,","so_s_tocsin":"data:image/webp;base64,","so_s_lance":"data:image/webp;base64,"},"abilities":{"so_bash":"data:image/webp;base64,","so_aegis":"data:image/webp;base64,","so_rebuke":"data:image/webp;base64,","so_sanct":"data:image/webp;base64,","so_hail":"data:image/webp;base64,","so_witness":"data:image/webp;base64,","so_bind":"data:image/webp;base64,","so_flare":"data:image/webp;base64,","so_shackle":"data:image/webp;base64,","so_grail":"data:image/webp;base64,","so_ridedown":"data:image/webp;base64,","so_vow":"data:image/webp;base64,","so_sunlance":"data:image/webp;base64,","so_halo":"data:image/webp;base64,","so_dawnfall":"data:image/webp;base64,","so_crush":"data:image/webp;base64,","so_hallow":"data:image/webp;base64,","so_hammerfall":"data:image/webp;base64,","so_sweep":"data:image/webp;base64,","so_smoke":"data:image/webp;base64,","so_embers":"data:image/webp;base64,","so_toll":"data:image/webp;base64,","so_peal":"data:image/webp;base64,","so_knell":"data:image/webp;base64,"},"spells":{"so_lioncharge":"data:image/webp;base64,","so_dawnbreak":"data:image/webp;base64,","so_sentence":"data:image/webp;base64,"},"heroes":{"so_lion":"data:image/webp;base64,","so_dawn":"data:image/webp;base64,","so_judge":"data:image/webp;base64,"}};
function silverArtApply() {
  const S = SILVERART;
  if (typeof RELICART !== 'undefined' && typeof RELIC_IMG !== 'undefined') for (const id in S.items) {
    const k = id.startsWith('so_s_') ? 'shop-' + id : id; if (RELICART[k] === S.items[id]) continue;
    const im = new Image(); RELICART[k] = S.items[id]; im.onload = () => { RELIC_IMG[k] = im; if (typeof onDirty === 'function') onDirty(); }; im.src = S.items[id];
  }
  if (typeof UI_ART !== 'undefined') { for (const id in S.abilities) UI_ART[id] = S.abilities[id]; for (const id in S.spells) UI_ART[id] = S.spells[id]; }
  if (typeof SPELL_ART !== 'undefined') for (const id in S.spells) SPELL_ART[id] = id;
  if (typeof HERO_ART !== 'undefined') for (const id in S.heroes) HERO_ART[id] = S.heroes[id];
}
if (typeof window !== 'undefined') { if (document.readyState === 'complete') setTimeout(silverArtApply, 0); else window.addEventListener('load', () => setTimeout(silverArtApply, 0)); }
